return items.map(item => {

  let tgl = item.json["Tanggal Transaksi"];
  let nominal = item.json["Jumlah (IDR)"];

  // ubah DD/MM/YYYY ke YYYY-MM-DD
  let parts = String(tgl).split('/');
  let cleanDate = `${parts[2]}-${parts[1]}-${parts[0]}`;

  // hapus non angka
  let cleanAmount = String(nominal).replace(/\D/g,'');

  return {
    json:{
      source: 'INTERNAL',
      row_number: item.json["row_number"],
      id_referensi: item.json["ID Referensi"],
      tanggal: cleanDate,
      nominal: cleanAmount,
      match_key: cleanDate + '_' + cleanAmount,
      deskripsi: item.json["Deskripsi"],
      tipe_transaksi: item.json["Tipe Transaksi"],
      status_internal: item.json["Status"],
      nama_vendor: item.json["Nama Klien/Vendor"],
      kategori: item.json["Kategori"]
    }
  };
});

