const items = $input.all();
const grouped = {};
const results = [];

// GROUP DATA
for (const item of items) {
  const data = item.json;
  const key = data.match_key;

  if (!grouped[key]) {
    grouped[key] = [];
  }

  grouped[key].push(data);
}

// ANALISA
for (const key in grouped) {

  const group = grouped[key];

  const internal = group.find(x => x.source === "INTERNAL");
  const bank = group.find(x => x.source === "BANK");

  let status = "";
  let pesan = "";

  if (internal && bank) {
    status = "MATCHED";
    pesan = "✅ Data cocok";
  } 
  else if (internal && !bank) {
    status = "UNRECORDED BANK";
    pesan = "⚠️ Ada di Internal, tidak ada di Bank";
  } 
  else if (!internal && bank) {
    status = "UNRECORDED INTERNAL";
    pesan = "⚠️ Ada di Bank, tidak ada di Internal";
  }

  const ref = internal || bank;

  results.push({
    json: {
      status: status,
      pesan: pesan,
      tanggal: ref?.tanggal || "-",
      nominal: ref?.nominal || 0,
      ref_internal: internal?.id_referensi || "-",
      ref_bank: bank?.id_referensi || 
          bank?.ref_bank || 
          bank?.deskripsi || 
          "-",
      deskripsi: ref?.deskripsi || "-",
      match_key: key
    }
  });
}

return results;

const data = $input.all().map(item => item.json);

// Summary
const total = data.length;
const matchedList = data.filter(x => x.status === "MATCHED");
const mismatchList = data.filter(x => x.status !== "MATCHED");

const matched = matchedList.length;
const mismatch = mismatchList.length;

// Ambil 1 contoh
const a = matchedList[0];
const b = mismatchList[0];

// PESAN 1
const pesan1 = `📊 LAPORAN REKONSILIASI

📁 Total Data: ${total}
✅ MATCHED: ${matched}
⚠️ MISMATCH: ${mismatch}

🕒 ${new Date().toLocaleString("id-ID")}
`;

// Function format
function formatItem(item, title) {
  if (!item) return `${title}\nTidak ada data\n`;

  return `${title}

📅 Tanggal: ${item.tanggal || "-"}
💰 Nominal: Rp ${Number(item.nominal || 0).toLocaleString("id-ID")}

⚠️ Status: ${item.status || "-"}
📝 Ket: ${item.pesan || "-"}

🔍 Ref Internal: ${item.ref_internal || "-"}
🏦 Ref Bank: ${item.ref_bank || "-"}

ℹ️ Desc: ${item.deskripsi || "-"}

`;
}

// PESAN 2
const pesan2 =
formatItem(a, "✅ CONTOH DATA MATCHED") +
"\n" +
formatItem(b, "⚠️ CONTOH DATA MISMATCH");

// Return 2 pesan
return [
  { json: { text: pesan1 } },
  { json: { text: pesan2 } }
];
